func TestSpoolCleanupKeepsUnrelatedAndForeignSlotFiles(t *testing.T) {
	c := newCell(t)
	s := c.stager()
	if err := os.MkdirAll(s.Spool, 0o700); err != nil {
		t.Fatal(err)
	}
