func materialProof(t *testing.T, roots trust.Keyring, root ed25519.PrivateKey, sequence uint64) release.VerifiedFunction {
	t.Helper()
	module := []byte("\x00asm\x01\x00\x00\x00")
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI, TenantID: entityid.New(), FunctionID: "echo", Revision: "v1", Digest: sum(module), Bytes: int64(len(module)), Environment: "production", Cell: "GRU", Sequence: sequence}
	public, leaf, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(public)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(public)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded, Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}}}, now.Add(-time.Minute), now.Add(2*time.Hour), root)
	if err != nil {
		t.Fatal(err)
	}
	receipt, err := release.SignFunctionClaim(claim, module, delegation, roots, leaf, now, time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(receipt)
	if err != nil {
		t.Fatal(err)
	}
	grant, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := release.VerifyFunctionCurrent(wire, grant, module, roots, release.FunctionExpectation{Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID, FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: sequence}, now)
	if err != nil {
		t.Fatal(err)
	}
	return proof
}

func materialVault(t *testing.T) (*ocivault.VaultsClient, *ocisecrets.SecretsClient, *vaultBackend, vaultsecret.Target) {
	t.Helper()
	backend := &vaultBackend{target: vaultsecret.Target{CompartmentID: "ocid1.compartment.oc1..function", VaultID: "ocid1.vault.oc1.sa-saopaulo-1.function", KeyID: "ocid1.key.oc1.sa-saopaulo-1.function"}}
	endpoint := httptest.NewServer(http.HandlerFunc(backend.serve))
	t.Cleanup(endpoint.Close)
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..function", "ocid1.user.oc1..function", "sa-saopaulo-1", "fp", string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil)
	vault, err := ocivault.NewVaultsClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	bundles, err := ocisecrets.NewSecretsClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	vault.Host, bundles.Host = endpoint.URL, endpoint.URL
	return &vault, &bundles, backend, backend.target
}

func (backend *vaultBackend) serve(w http.ResponseWriter, r *http.Request) {
	backend.mu.Lock()
	defer backend.mu.Unlock()
	w.Header().Set("Content-Type", "application/json")
	write := func(value any) {
		wire, err := json.Marshal(value)
		if err != nil {
			http.Error(w, "encode", 500)
			return
		}
		_, _ = w.Write(wire)
	}
	metadata := func() map[string]any {
		return map[string]any{"id": materialSecretID, "vaultId": backend.target.VaultID, "secretName": backend.name, "lifecycleState": "ACTIVE", "currentVersionNumber": backend.version}
	}
	switch {
	case r.Method == "GET" && strings.HasSuffix(r.URL.Path, "/secrets"):
		if backend.name == "" {
			write([]any{})
			return
		}
		write([]any{metadata()})
	case r.Method == "POST" && strings.HasSuffix(r.URL.Path, "/secrets"):
		var input struct {
			SecretName    string `json:"secretName"`
			SecretContent struct {
				Content string `json:"content"`
			} `json:"secretContent"`
		}
		body, _ := io.ReadAll(io.LimitReader(r.Body, 64<<10))
		if json.Unmarshal(body, &input) != nil || backend.name != "" {
			http.Error(w, "conflict", 409)
			return
		}
		value, err := base64.StdEncoding.DecodeString(input.SecretContent.Content)
		if err != nil {
			http.Error(w, "content", 400)
			return
		}
		backend.name, backend.value, backend.version = input.SecretName, value, 1
		backend.creates++
		w.WriteHeader(200)
		write(metadata())
	case r.Method == "GET" && strings.Contains(r.URL.Path, "/secrets/"):
		w.Header().Set("ETag", fmt.Sprint(backend.version))
		write(metadata())
	case r.Method == "PUT" && strings.Contains(r.URL.Path, "/secrets/"):
		if r.Header.Get("If-Match") != fmt.Sprint(backend.version) {
			http.Error(w, "changed", 412)
			return
		}
		var input struct {
			SecretContent struct {
				Content string `json:"content"`
			} `json:"secretContent"`
		}
		body, _ := io.ReadAll(io.LimitReader(r.Body, 64<<10))
		if json.Unmarshal(body, &input) != nil {
			http.Error(w, "content", 400)
			return
		}
		value, err := base64.StdEncoding.DecodeString(input.SecretContent.Content)
		if err != nil {
			http.Error(w, "content", 400)
			return
		}
		backend.value = value
		backend.version++
		backend.updates++
		write(metadata())
	case r.Method == "POST" && strings.HasSuffix(r.URL.Path, "/secretbundles/actions/getByName"):
		write(map[string]any{"secretId": materialSecretID, "versionNumber": backend.version, "secretBundleContent": map[string]any{"contentType": "BASE64", "content": base64.StdEncoding.EncodeToString(backend.value)}})
	default:
		http.Error(w, "unknown route", 404)
	}
}

func verifyMaterialTLSConnection(t *testing.T, files map[string][]byte, proof release.VerifiedFunction) {
	t.Helper()
	cert, err := tls.X509KeyPair(files["ingress-cert.pem"], files["ingress-key.pem"])
	if err != nil {
		t.Fatal(err)
	}
	endpoint := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(http.StatusNoContent) }))
	endpoint.TLS = &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{cert}}
	endpoint.StartTLS()
	defer endpoint.Close()
	pool := x509.NewCertPool()
	pool.AppendCertsFromPEM(files["ingress-ca.pem"])
	claim := proof.Claim()
	name := claim.FunctionID + "." + strings.ToLower(claim.TenantID) + ".functions.gru.terrascale.internal"
	client := &http.Client{Transport: &http.Transport{TLSClientConfig: &tls.Config{MinVersion: tls.VersionTLS13, RootCAs: pool, ServerName: name}}}
	defer client.CloseIdleConnections()
	response, err := client.Get(endpoint.URL)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusNoContent {
		t.Fatal("function TLS endpoint unavailable")
	}
}

func (controller Controller) Prepare(ctx context.Context, tenant, function string, binding Binding) (VerifiedDelivery, error) {
	if controller.Authority == nil || controller.Conn == nil || controller.Issuer == nil || controller.Vault == nil || controller.Versions == nil || controller.AuthorizeRecipient == nil || controller.Reader.Bundles == nil || controller.Target.VaultID != controller.Reader.VaultID {
		return VerifiedDelivery{}, ErrMaterial
	}
	if err := controller.AuthorizeRecipient(ctx, binding); err != nil {
		return VerifiedDelivery{}, err
	}
	reader := controller.Reader
	reader.Authority = controller.Authority
	reader.AuthorizeRecipient = controller.AuthorizeRecipient
	reader.Recipient = Recipient{NodeID: binding.NodeID, InstanceID: binding.InstanceID, Region: binding.Region, HostID: binding.HostID}
	ref, err := secretRef(reader.VaultID, binding)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	proof, sequence, err := reader.currentFunction(ctx, tenant, function)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	if catalog.OCIRegion(proof.Claim().Cell) != binding.Region {
		return VerifiedDelivery{}, ErrMaterial
	}
	if err := vaultsecret.ValidateDeliveryRefs(strings.ToLower(proof.Claim().Cell), "function-worker", map[string]vaultsecret.Ref{"FUNCTION_MATERIAL_FILE": ref}, nil); err != nil {
		return VerifiedDelivery{}, err
	}
	account, err := reader.currentAccount(ctx, proof)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	if entry, err := controller.Authority.ReadFunctionGrant(ctx, binding.TaskID); err == nil {
		grant, err := authority.DecodeFunctionGrant(entry)
		if err != nil || grant.TenantID != tenant || grant.FunctionID != function || grant.EnvelopeSHA256 != proof.EnvelopeSHA256() {
			return VerifiedDelivery{}, ErrMaterial
		}
		return reader.Current(ctx, binding)
	} else if !errors.Is(err, authority.ErrNotFound) {
		return VerifiedDelivery{}, err
	}
	epoch := controller.Authority.Current().Epoch
	guard := func() error { return controller.Authority.Guard(ctx, epoch) }
	if err := guard(); err != nil {
		return VerifiedDelivery{}, err
	}
	if err := functions.ProvisionQueue(ctx, controller.Conn, proof); err != nil {
		return VerifiedDelivery{}, err
	}
	_, err = vaultsecret.Ensure(ctx, controller.Vault, controller.Target, ref.Name, "Admitted function task material", func(ctx context.Context) (string, error) {
		if err := guard(); err != nil {
			return "", err
		}
		material, err := controller.issue(reader, proof, sequence, account, binding, nil)
		if err != nil {
			return "", err
		}
		wire, err := encodeMaterial(material)
		if err != nil {
			return "", err
		}
		defer clear(wire)
		return string(wire), nil
	})
	if err != nil {
		return VerifiedDelivery{}, err
	}
	current, err := vaultsecret.ReadCurrent(ctx, reader.Bundles, ref)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	wire := []byte(current.Value())
	defer func() { clear(wire) }()
	material, err := decodeMaterial(wire)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	if material.Binding != binding || material.TenantID != tenant || material.FunctionID != function || material.EnvelopeSHA256 != proof.EnvelopeSHA256() || material.IntentSequence != sequence {
		return VerifiedDelivery{}, ErrMaterial
	}
	// Issuance validates old grants and keeps the key even when renewal is needed.
	credentials, _, err := controller.Issuer.IssueFunctionCredentials(proof, account.JWT, material.Files["broker.creds"])
	if err != nil {
		return VerifiedDelivery{}, err
	}
	defer clear(credentials)
	if _, err := reader.verifyMaterial(material, binding, proof, sequence, account); err != nil {
		material, err = controller.issue(reader, proof, sequence, account, binding, material.Files["broker.creds"])
		if err != nil {
			return VerifiedDelivery{}, err
		}
		next, err := encodeMaterial(material)
		if err != nil {
			return VerifiedDelivery{}, err
		}
		defer clear(next)
		if err := controller.recheck(ctx, reader, proof, sequence, account, binding, epoch); err != nil {
			return VerifiedDelivery{}, err
		}
		if _, err := vaultsecret.PublishVersion(ctx, controller.Versions, ref, current.ID, current.Version, next); err != nil {
			return VerifiedDelivery{}, err
		}
		readback, err := vaultsecret.ReadCurrent(ctx, reader.Bundles, ref)
		if err != nil {
			return VerifiedDelivery{}, err
		}
		if readback.ID != current.ID || readback.Version <= current.Version || !bytes.Equal([]byte(readback.Value()), next) {
			return VerifiedDelivery{}, ErrMaterial
		}
		clear(wire)
		wire = bytes.Clone(next)
	}
	if _, err := reader.verifyMaterial(material, binding, proof, sequence, account); err != nil {
		return VerifiedDelivery{}, err
	}
	if err := controller.recheck(ctx, reader, proof, sequence, account, binding, epoch); err != nil {
		return VerifiedDelivery{}, err
	}
	manifest := sum(wire)
	operation := entityid.Derive("function-material", binding.TaskID, proof.EnvelopeSHA256(), manifest)
	if _, err := controller.Authority.CommitFunctionGrant(ctx, epoch, operation, 0, proof, bindingGrant(binding, manifest)); err != nil {
		return VerifiedDelivery{}, err
	}
	return reader.Current(ctx, binding)
}

func (controller Controller) recheck(ctx context.Context, reader Reader, proof release.VerifiedFunction, sequence uint64, account brokerauth.Claim, binding Binding, epoch uint64) error {
	if err := controller.Authority.Guard(ctx, epoch); err != nil {
		return err
	}
	if err := controller.AuthorizeRecipient(ctx, binding); err != nil {
		return err
	}
	next, nextSequence, err := reader.currentFunction(ctx, proof.Claim().TenantID, proof.Claim().FunctionID)
	if err != nil {
		return err
	}
	if nextSequence != sequence || next.EnvelopeSHA256() != proof.EnvelopeSHA256() {
		return ErrMaterial
	}
	after, err := reader.currentAccount(ctx, proof)
	if err != nil {
		return err
	}
	if after.Sequence != account.Sequence || after.Hash != account.Hash {
		return ErrMaterial
	}
	return nil
}

func (controller Controller) issue(reader Reader, proof release.VerifiedFunction, sequence uint64, account brokerauth.Claim, binding Binding, existing []byte) (storedMaterial, error) {
	credentials, identity, err := controller.Issuer.IssueFunctionCredentials(proof, account.JWT, existing)
	if err != nil {
		return storedMaterial{}, err
	}
	cert, key, issuer, err := controller.Issuer.IssueFunctionTLS(proof)
	if err != nil {
		clear(credentials)
		return storedMaterial{}, err
	}
	files := map[string][]byte{"broker.creds": credentials, "broker-ca.pem": bytes.Clone(reader.Trust.brokerCA), "ingress-cert.pem": cert, "ingress-key.pem": key, "ingress-ca.pem": issuer}
	tlsExpiry, err := verifyTLS(files, proof)
	if err != nil {
		for _, value := range files {
			clear(value)
		}
		return storedMaterial{}, err
	}
	return storedMaterial{Schema: 1, Binding: binding, TenantID: proof.Claim().TenantID, FunctionID: proof.Claim().FunctionID, EnvelopeSHA256: proof.EnvelopeSHA256(), IntentSequence: sequence, AccountSequence: account.Sequence, Generation: reader.Trust.fingerprint, ExpiresAt: minTime(proof.ExpiresAt(), identity.ExpiresAt, tlsExpiry, reader.Trust.expiresAt), Files: files}, nil
}

func encodeMaterial(material storedMaterial) ([]byte, error) {
	if !time.Now().Before(material.ExpiresAt) {
		return nil, ErrMaterial
	}
	wire, err := json.Marshal(material)
	if err != nil {
		return nil, err
	}
	if len(wire) > 16384 {
		clear(wire)
		return nil, errors.New("function credentials and TLS material exceed Vault's 16 KiB bound")
	}
	return wire, nil
}

func (reader Reader) currentFunction(ctx context.Context, tenant, function string) (release.VerifiedFunction, uint64, error) {
	if reader.Authority == nil || reader.Artifacts == nil || reader.Roots == nil {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	entry, err := reader.Authority.ReadFunctionIntent(ctx, tenant, function)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	intent, err := authority.DecodeFunctionIntent(entry)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	claim := intent.Claim
	info, err := reader.Artifacts.GetInfo(ctx, "sha256-"+claim.Digest)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	if info.Size != uint64(claim.Bytes) || info.Size == 0 || info.Size > release.MaxFunctionModuleBytes || info.Opts != nil && info.Opts.Link != nil {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	object, err := reader.Artifacts.Get(ctx, "sha256-"+claim.Digest)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	module, readErr := io.ReadAll(io.LimitReader(object, release.MaxFunctionModuleBytes+1))
	closeErr := object.Close()
	if readErr != nil || closeErr != nil || len(module) > release.MaxFunctionModuleBytes {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	proof, err := release.VerifyFunctionCurrent(intent.Envelope, intent.Delegation, module, reader.Roots(), release.FunctionExpectation{
		Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID, FunctionID: claim.FunctionID,
		Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: claim.Sequence,
	}, time.Now())
	if err != nil || proof.EnvelopeSHA256() != intent.EnvelopeSHA256 {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	return proof, entry.Sequence, nil
}

func (reader Reader) Current(ctx context.Context, binding Binding) (VerifiedDelivery, error) {
	if reader.Authority == nil || reader.Bundles == nil || reader.AuthorizeRecipient == nil || reader.Recipient != (Recipient{NodeID: binding.NodeID, InstanceID: binding.InstanceID, Region: binding.Region, HostID: binding.HostID}) {
		return VerifiedDelivery{}, ErrMaterial
	}
	if err := reader.AuthorizeRecipient(ctx, binding); err != nil {
		return VerifiedDelivery{}, err
	}
	entry, err := reader.Authority.ReadFunctionGrant(ctx, binding.TaskID)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	grant, err := authority.DecodeFunctionGrant(entry)
	if err != nil || grant.Binding != bindingGrant(binding, grant.Binding.MaterialManifestSHA256) {
		return VerifiedDelivery{}, ErrMaterial
	}
	proof, intentSequence, err := reader.currentFunction(ctx, grant.TenantID, grant.FunctionID)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	if grant.EnvelopeSHA256 != proof.EnvelopeSHA256() || grant.Sequence != proof.Claim().Sequence || catalog.OCIRegion(proof.Claim().Cell) != binding.Region {
		return VerifiedDelivery{}, ErrMaterial
	}
	account, err := reader.currentAccount(ctx, proof)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	ref, err := secretRef(reader.VaultID, binding)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	if err := vaultsecret.ValidateDeliveryRefs(strings.ToLower(reader.Trust.cell), "function-worker", map[string]vaultsecret.Ref{"FUNCTION_MATERIAL_FILE": ref}, nil); err != nil {
		return VerifiedDelivery{}, err
	}
	current, err := vaultsecret.ReadCurrent(ctx, reader.Bundles, ref)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	wire := []byte(current.Value())
	defer clear(wire)
	if sum(wire) != grant.Binding.MaterialManifestSHA256 {
		return VerifiedDelivery{}, ErrMaterial
	}
	material, err := decodeMaterial(wire)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	validity, err := reader.verifyMaterial(material, binding, proof, intentSequence, account)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	files, err := filesFor(proof, proof.Claim().Sequence, reader.Roots(), material, reader.Trust.brokerURL)
	if err != nil {
		return VerifiedDelivery{}, err
	}
	latest, latestSequence, err := reader.currentFunction(ctx, grant.TenantID, grant.FunctionID)
	if err != nil || latestSequence != intentSequence || latest.EnvelopeSHA256() != proof.EnvelopeSHA256() {
		return VerifiedDelivery{}, ErrMaterial
	}
	after, err := reader.currentAccount(ctx, proof)
	if err != nil || after.Sequence != account.Sequence || after.Hash != account.Hash {
		return VerifiedDelivery{}, ErrMaterial
	}
	if err := reader.AuthorizeRecipient(ctx, binding); err != nil {
		return VerifiedDelivery{}, err
	}
	return VerifiedDelivery{binding: binding, function: proof, minimum: proof.Claim().Sequence, expires: validity.delivery, credentialExpires: validity.credentials, files: files}, nil
}

func decodeMaterial(wire []byte) (storedMaterial, error) {
	var material storedMaterial
	if len(wire) == 0 || len(wire) > 16384 || json.Unmarshal(wire, &material, json.RejectUnknownMembers(true)) != nil || material.Schema != 1 || len(material.Files) != 5 {
		return storedMaterial{}, ErrMaterial
	}
	for _, name := range []string{"broker.creds", "broker-ca.pem", "ingress-cert.pem", "ingress-key.pem", "ingress-ca.pem"} {
		if len(material.Files[name]) == 0 {
			return storedMaterial{}, ErrMaterial
		}
	}
	return material, nil
}

type verifiedMaterialExpiry struct {
	delivery, credentials time.Time
}

func (reader Reader) verifyMaterial(material storedMaterial, binding Binding, proof release.VerifiedFunction, intentSequence uint64, account brokerauth.Claim) (verifiedMaterialExpiry, error) {
	claim := proof.Claim()
	if material.Binding != binding || material.TenantID != claim.TenantID || material.FunctionID != claim.FunctionID || material.EnvelopeSHA256 != proof.EnvelopeSHA256() ||
		material.IntentSequence != intentSequence || material.AccountSequence != account.Sequence || material.Generation != reader.Trust.fingerprint ||
		!bytes.Equal(material.Files["broker-ca.pem"], reader.Trust.brokerCA) {
		return verifiedMaterialExpiry{}, ErrMaterial
	}
	if sum(material.Files["ingress-ca.pem"]) != reader.Trust.issuerSHA256 {
		return verifiedMaterialExpiry{}, ErrMaterial
	}
	identity, err := functions.VerifyWorkerCredentials(proof, account.Account, account.JWT, material.Files["broker.creds"])
	if err != nil {
		return verifiedMaterialExpiry{}, err
	}
	tlsExpiry, err := verifyTLS(material.Files, proof)
	if err != nil {
		return verifiedMaterialExpiry{}, err
	}
	expires := minTime(proof.ExpiresAt(), identity.ExpiresAt, tlsExpiry, reader.Trust.expiresAt)
	if material.ExpiresAt.After(expires) || !time.Now().Before(material.ExpiresAt) {
		return verifiedMaterialExpiry{}, ErrMaterial
	}
	return verifiedMaterialExpiry{delivery: material.ExpiresAt, credentials: minTime(identity.ExpiresAt, tlsExpiry)}, nil
}

func NewPublicTrust(generation bootstrap.VerifiedMaterialGeneration, operatorJWT, brokerCA []byte, brokerURL string) (PublicTrust, error) {
	if generation.Fingerprint() == "" || !time.Now().Before(generation.ExpiresAt()) {
		return PublicTrust{}, ErrMaterial
	}
	gen := generation.Generation()
	pinned := func(name string, value []byte) bool {
		for _, ref := range gen.Secrets {
			if ref.TargetFile == name {
				return len(value) > 0 && int64(len(value)) <= ref.MaxBytes && sum(value) == ref.SHA256
			}
		}
		return false
	}
	issuerSHA256 := ""
	for _, ref := range gen.Secrets {
		if ref.TargetFile == "controller-tls-issuer-cert.pem" {
			issuerSHA256 = ref.SHA256
		}
	}
	if !pinned("operator.jwt", operatorJWT) || !pinned("ca.pem", brokerCA) {
		return PublicTrust{}, ErrMaterial
	}
	return newPublicTrust(PublicTrust{fingerprint: generation.Fingerprint(), cell: string(gen.Cell), environment: gen.Environment,
		cellAccount: gen.CellAccount, accountSigner: gen.AccountSigner, issuerSHA256: issuerSHA256, expiresAt: generation.ExpiresAt()}, gen.Operator, operatorJWT, brokerCA, brokerURL)
}

func newPublicTrust(identity PublicTrust, operatorKey string, operatorJWT, brokerCA []byte, brokerURL string) (PublicTrust, error) {
	if !materialDigest(identity.fingerprint) || !materialDigest(identity.issuerSHA256) || !catalog.IsCell(identity.cell) ||
		identity.environment != "production" && identity.environment != "canary" || !nkeys.IsValidPublicOperatorKey(operatorKey) ||
		!nkeys.IsValidPublicAccountKey(identity.cellAccount) || !nkeys.IsValidPublicAccountKey(identity.accountSigner) || !time.Now().Before(identity.expiresAt) {
		return PublicTrust{}, ErrMaterial
	}
	operator, err := jwt.DecodeOperatorClaims(strings.TrimSpace(string(operatorJWT)))
	if err != nil || operator.Subject != operatorKey || operator.Issuer != operatorKey || !operator.DidSign(operator) {
		return PublicTrust{}, ErrMaterial
	}
	validation := jwt.CreateValidationResults()
	operator.Validate(validation)
	if validation.IsBlocking(true) {
		return PublicTrust{}, ErrMaterial
	}
	endpoint, err := url.Parse(brokerURL)
	if err != nil || endpoint.Scheme != "tls" || endpoint.Hostname() == "" || endpoint.User != nil || endpoint.Path != "" || endpoint.RawQuery != "" || endpoint.Fragment != "" {
		return PublicTrust{}, ErrMaterial
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(brokerCA) {
		return PublicTrust{}, ErrMaterial
	}
	if operator.Expires != 0 {
		identity.expiresAt = minTime(identity.expiresAt, time.Unix(operator.Expires, 0))
	}
	identity.operator, identity.brokerCA, identity.brokerURL = operator, bytes.Clone(brokerCA), brokerURL
	return identity, nil
}

func (delivery VerifiedDelivery) Binding() Binding                   { return delivery.binding }
func (delivery VerifiedDelivery) Function() release.VerifiedFunction { return delivery.function }
func (delivery VerifiedDelivery) MinimumSequence() uint64            { return delivery.minimum }
func (delivery VerifiedDelivery) ExpiresAt() time.Time               { return delivery.expires }
func (delivery VerifiedDelivery) CredentialExpiresAt() time.Time     { return delivery.credentialExpires }
func (delivery VerifiedDelivery) Valid() bool {
	return delivery.function.Valid() && time.Now().Before(delivery.expires) && len(delivery.files) == 10
}
func (delivery VerifiedDelivery) Files() map[string][]byte {
	files := make(map[string][]byte, len(delivery.files))
	for name, value := range delivery.files {
		files[name] = bytes.Clone(value)
	}
	return files
}

func secretRef(vault string, binding Binding) (vaultsecret.Ref, error) {
	if err := bindingGrant(binding, strings.Repeat("a", 64)).Validate(); err != nil {
		return vaultsecret.Ref{}, ErrMaterial
	}
	region, known := catalog.CellForOCIRegion(binding.Region)
	if !known {
		return vaultsecret.Ref{}, ErrMaterial
	}
	wire, err := json.Marshal(binding)
	if err != nil {
		return vaultsecret.Ref{}, err
	}
	return vaultsecret.Ref{Vault: vault, Name: region.Name() + "-function-worker-" + sum(wire)}, nil
}

func (reader Reader) currentAccount(ctx context.Context, proof release.VerifiedFunction) (brokerauth.Claim, error) {
	if reader.Accounts == nil || reader.Trust.operator == nil || !time.Now().Before(reader.Trust.expiresAt) || !proof.Valid() {
		return brokerauth.Claim{}, ErrMaterial
	}
	claim := proof.Claim()
	if claim.Environment != reader.Trust.environment || claim.Cell != reader.Trust.cell {
		return brokerauth.Claim{}, ErrMaterial
	}
	account, err := reader.Accounts.Read(ctx, reader.Trust.cellAccount)
	if err != nil {
		return brokerauth.Claim{}, err
	}
	decoded, err := brokerauth.DecodeAccountJWT(account.JWT, reader.Trust.cellAccount)
	if err != nil || account.Sequence == 0 || account.Account != reader.Trust.cellAccount || account.Cell != strings.ToLower(reader.Trust.cell) || !reader.Trust.operator.DidSign(decoded) {
		return brokerauth.Claim{}, ErrMaterial
	}
	scope, registered := decoded.SigningKeys.GetScope(reader.Trust.accountSigner)
	if !registered || scope != nil {
		return brokerauth.Claim{}, ErrMaterial
	}
	return account, nil
}

func verifyTLS(files map[string][]byte, proof release.VerifiedFunction) (time.Time, error) {
	certificate, err := tls.X509KeyPair(files["ingress-cert.pem"], files["ingress-key.pem"])
	if err != nil || len(certificate.Certificate) == 0 {
		return time.Time{}, ErrMaterial
	}
	leaf, err := x509.ParseCertificate(certificate.Certificate[0])
	if err != nil || leaf.IsCA || !slices.Equal(leaf.ExtKeyUsage, []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}) {
		return time.Time{}, ErrMaterial
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(files["ingress-ca.pem"]) {
		return time.Time{}, ErrMaterial
	}
	intermediates := x509.NewCertPool()
	for _, der := range certificate.Certificate[1:] {
		cert, err := x509.ParseCertificate(der)
		if err != nil {
			return time.Time{}, ErrMaterial
		}
		intermediates.AddCert(cert)
	}
	claim := proof.Claim()
	dns := claim.FunctionID + "." + strings.ToLower(claim.TenantID) + ".functions." + strings.ToLower(claim.Cell) + ".terrascale.internal"
	uri := "spiffe://terrascale.tech/tenants/" + claim.TenantID + "/functions/" + claim.FunctionID
	if len(leaf.URIs) != 1 || leaf.URIs[0].String() != uri || len(leaf.DNSNames) != 1 || leaf.DNSNames[0] != dns || len(leaf.IPAddresses) != 0 || len(leaf.EmailAddresses) != 0 {
		return time.Time{}, ErrMaterial
	}
	if _, err := leaf.Verify(x509.VerifyOptions{Roots: pool, Intermediates: intermediates, DNSName: dns, KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}}); err != nil {
		return time.Time{}, ErrMaterial
	}
	return leaf.NotAfter, nil
}

func bindingGrant(binding Binding, manifest string) authority.FunctionBinding {
	return authority.FunctionBinding{TaskID: binding.TaskID, ServiceID: binding.ServiceID, NodeID: binding.NodeID, InstanceID: binding.InstanceID, Region: binding.Region, HostID: binding.HostID, Fingerprint: binding.Fingerprint, MaterialManifestSHA256: manifest}
}

func filesFor(proof release.VerifiedFunction, minimum uint64, roots trust.Keyring, material storedMaterial, brokerURL string) (map[string][]byte, error) {
	claim := proof.Claim()
	delegation, err := trust.DecodeEnvelope(proof.Delegation())
	if err != nil {
		return nil, err
	}
	root := roots[delegation.KeyID]
	if len(root) != 32 {
		return nil, ErrMaterial
	}
	deployment, err := json.Marshal(functions.ProcessDeployment{Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID, FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: minimum, BrokerURL: brokerURL, ExpiresAt: material.ExpiresAt})
	if err != nil {
		return nil, err
	}
	files := make(map[string][]byte, 10)
	for name, value := range material.Files {
		files[name] = bytes.Clone(value)
	}
	files["deployment.json"], files["root.pub"], files["module.wasm"] = deployment, bytes.Clone(root), proof.Module()
	files["receipt.json"], files["delegation.json"] = proof.Envelope(), proof.Delegation()
	return files, nil
}

func Ensure(ctx context.Context, client VaultClient, target Target, name, description string, value func(context.Context) (string, error)) (Stored, error) {
	stored := Stored{Secret: name}
	if err := safeEnv(); err != nil {
		return stored, err
	}
	id, provisioning, err := lookup(ctx, client, target, name)
	if err != nil || id != "" {
		stored.ID = id
		stored.Provisioning = provisioning
		return stored, err
	}
	secret, err := value(ctx)
	if err != nil {
		return stored, err
	}
	content := base64.StdEncoding.EncodeToString([]byte(secret))
	response, err := client.CreateSecret(ctx, ocivault.CreateSecretRequest{
		CreateSecretDetails: ocivault.CreateSecretDetails{
			CompartmentId: new(target.CompartmentID), VaultId: new(target.VaultID), KeyId: new(target.KeyID),
			SecretName: new(name), Description: new(description),
			SecretContent: ocivault.Base64SecretContentDetails{Content: new(content), Stage: ocivault.SecretContentDetailsStageCurrent},
		},
		// The SDK retries a lost response with the same token, which OCI
		// answers with the first result instead of a second secret.
		OpcRetryToken: new(uuid.New().String()),
	})
	if err != nil {
		if id, provisioning, lookupErr := lookup(ctx, client, target, name); lookupErr == nil && id != "" {
			stored.ID, stored.Provisioning = id, provisioning
			return stored, nil
		}
		return stored, fmt.Errorf("create Vault secret %s failed", name)
	}
	if response.Id == nil || !secretOCIDRE.MatchString(*response.Id) {
		return stored, fmt.Errorf("create Vault secret %s: OCI returned no secret OCID", name)
	}
	stored.ID, stored.Created = *response.Id, true
	return stored, nil
}

// lookup returns the OCID of the active secret name, or "" when the Vault has
// none. A secret of that name in any other state needs an operator: it may be
// pending deletion, and OCI refuses its name until it is deleted.
func lookup(ctx context.Context, client VaultClient, target Target, name string) (string, bool, error) {
	found := ""
	provisioning := false
	request := ocivault.ListSecretsRequest{CompartmentId: new(target.CompartmentID), VaultId: new(target.VaultID), Name: new(name)}
	for range 32 {
		response, err := client.ListSecrets(ctx, request)
		if err != nil {
			return "", false, fmt.Errorf("list Vault secret %s failed", name)
		}
		for _, item := range response.Items {
			if item.SecretName == nil || *item.SecretName != name {
				continue
			}
			if item.Id == nil || !secretOCIDRE.MatchString(*item.Id) || found != "" ||
				item.LifecycleState != ocivault.SecretSummaryLifecycleStateActive &&
					item.LifecycleState != ocivault.SecretSummaryLifecycleStateCreating {
				return "", false, fmt.Errorf("Vault secret %s exists in state %s; inspect it before rerunning", name, item.LifecycleState)
			}
			found = *item.Id
			provisioning = item.LifecycleState == ocivault.SecretSummaryLifecycleStateCreating
		}
		if response.OpcNextPage == nil {
			return found, provisioning, nil
		}
		request.Page = response.OpcNextPage
	}
	return "", false, fmt.Errorf("list Vault secret %s: too many pages", name)
}

func readBundle(ctx context.Context, client BundleClient, vaultID, name string) (ocisecrets.GetSecretBundleByNameResponse, error) {
	if err := safeEnv(); err != nil {
		return ocisecrets.GetSecretBundleByNameResponse{}, err
	}
	response, err := client.GetSecretBundleByName(ctx, ocisecrets.GetSecretBundleByNameRequest{
		SecretName: new(name), VaultId: new(vaultID), Stage: ocisecrets.GetSecretBundleByNameStageCurrent,
	})
	if err != nil {
		return response, &readError{name: name, cause: err}
	}
	return response, nil
}

// Keep the SDK error available for retry classification, without printing
// a response body that might contain secret material.
type readError struct {
	name  string
	cause error
}

func (e *readError) Error() string    { return "read Vault secret " + e.name + " failed" }
func (e *readError) Unwrap() error    { return e.cause }
func (e *readError) GoString() string { return e.Error() }

func decodeBundle(bundle ocisecrets.SecretBundle, name string) (string, error) {
	var content *string
	switch bundle := bundle.SecretBundleContent.(type) {
	case ocisecrets.Base64SecretBundleContentDetails:
		content = bundle.Content
	case *ocisecrets.Base64SecretBundleContentDetails:
		if bundle != nil {
			content = bundle.Content
		}
	}
	if content == nil {
		return "", fmt.Errorf("Vault secret %s has no base64 content", name)
	}
	if len(*content) > base64.StdEncoding.EncodedLen(maxValue) {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	value, err := base64.StdEncoding.Strict().DecodeString(*content)
	if err != nil {
		return "", fmt.Errorf("Vault secret %s is not base64", name)
	}
	if len(value) > maxValue {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	return string(value), nil
}

// ReadCurrent returns the CURRENT version, never LATEST or PENDING.
func ReadCurrent(ctx context.Context, client BundleClient, ref Ref) (Current, error) {
	if ref.region() == "" || len(ref.Name) > 255 || !nameRE.MatchString(ref.Name) {
		return Current{}, errors.New("Vault current read requires a regional Vault and a secret name")
	}
	bundle, err := readBundle(ctx, client, ref.Vault, ref.Name)
	if err != nil {
		return Current{}, err
	}
	if bundle.SecretId == nil || !secretOCIDRE.MatchString(*bundle.SecretId) ||
		strings.Split(*bundle.SecretId, ".")[3] != ref.region() ||
		bundle.VersionNumber == nil || *bundle.VersionNumber < 1 ||
		bundle.TimeOfExpiry != nil && !time.Now().Before(bundle.TimeOfExpiry.Time) ||
		bundle.TimeOfDeletion != nil && !time.Now().Before(bundle.TimeOfDeletion.Time) {
		return Current{}, fmt.Errorf("Vault secret %s returned invalid or expired version metadata", ref.Name)
	}
	value, err := decodeBundle(bundle.SecretBundle, ref.Name)
	if err != nil {
		return Current{}, err
	}
	expires := time.Time{}
	for _, deadline := range []*common.SDKTime{bundle.TimeOfExpiry, bundle.TimeOfDeletion} {
		if deadline != nil && (expires.IsZero() || deadline.Time.Before(expires)) {
			expires = deadline.Time
		}
	}
	return Current{ID: *bundle.SecretId, Version: *bundle.VersionNumber, ExpiresAt: expires, value: value}, nil

func PublishVersion(ctx context.Context, client VersionClient, ref Ref, id string, expected int64, value []byte) (Stored, error) {
	if err := safeEnv(); err != nil {
		return Stored{}, err
	}
	if ref.region() == "" || !nameRE.MatchString(ref.Name) || len(ref.Name) > 255 ||
		!secretOCIDRE.MatchString(id) || strings.Split(id, ".")[3] != ref.region() || expected < 1 || len(value) == 0 || len(value) > maxValue {
		return Stored{}, errors.New("Vault publication requires a regional named secret, an expected version and 1 to 16384 bytes")
	}
	before, err := client.GetSecret(ctx, ocivault.GetSecretRequest{SecretId: new(id)})
	if err != nil {
		return Stored{}, fmt.Errorf("read Vault metadata for %s failed", ref.Name)
	}
	if before.Id == nil || *before.Id != id || before.VaultId == nil || *before.VaultId != ref.Vault ||
		before.SecretName == nil || *before.SecretName != ref.Name ||
		before.LifecycleState != ocivault.SecretLifecycleStateActive || before.Etag == nil || *before.Etag == "" {
		return Stored{}, errors.New("Vault publication target differs from its named regional reference")
	}
	if before.CurrentVersionNumber == nil || *before.CurrentVersionNumber != expected {
		return Stored{}, ErrVersionConflict
	}
	content := base64.StdEncoding.EncodeToString(value)
	after, err := client.UpdateSecret(ctx, ocivault.UpdateSecretRequest{
		SecretId: new(id), IfMatch: before.Etag,
		UpdateSecretDetails: ocivault.UpdateSecretDetails{SecretContent: ocivault.Base64SecretContentDetails{
			Content: new(content), Stage: ocivault.SecretContentDetailsStageCurrent,
		}},
	})
	if err != nil {
		return Stored{}, fmt.Errorf("publish Vault secret %s failed; reread CURRENT before retrying", ref.Name)
	}
	if after.Id == nil || *after.Id != id || after.CurrentVersionNumber == nil || *after.CurrentVersionNumber <= expected {
		return Stored{}, errors.New("Vault publication returned uncertain version metadata; reread CURRENT before retrying")
	}
	return Stored{Secret: ref.Name, ID: id}, nil
}

func (r *Runtime) CommitFunctionIntent(ctx context.Context, epoch uint64, operationID string,
	expectedSequence uint64, proof release.VerifiedFunction,
) (uint64, error) {
	if !proof.Valid() {
		return 0, trust.ErrExpired
	}
	intent := FunctionIntent{Claim: proof.Claim(), EnvelopeSHA256: proof.EnvelopeSHA256(),
		Envelope: proof.Envelope(), Delegation: proof.Delegation()}
	key, err := functionIntentKey(intent.Claim.TenantID, intent.Claim.FunctionID)
	if err != nil {
		return 0, err
	}
	if r == nil || strings.ToLower(intent.Claim.Cell) != r.config.Scope {
		return 0, release.ErrExpectationMismatch
	}
	payload, err := json.Marshal(intent, json.FormatNilSliceAsNull(true))
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationFunctionIntent, key, operationID,
		expectedSequence, payload, func(ctx context.Context) error {
			if !proof.Valid() {
				return trust.ErrExpired
			}
			prior, err := r.ReadFunctionIntent(ctx, intent.Claim.TenantID, intent.Claim.FunctionID)
			if !proof.Valid() {
				return trust.ErrExpired
			}
			if errors.Is(err, ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			current, err := DecodeFunctionIntent(prior)
			if err != nil {
				return err
			}
			if intent.Claim.Sequence < current.Claim.Sequence ||
				intent.Claim.Sequence == current.Claim.Sequence && !bytes.Equal(payload, prior.Payload) {
				return ErrConflict
			}
			return nil
		})
}

func (r *Runtime) ReadFunctionIntent(ctx context.Context, tenantID, functionID string) (LogEntry, error) {
	key, err := functionIntentKey(tenantID, functionID)
	if err != nil {
		return LogEntry{}, err
	}
	return r.ReadHostMutation(ctx, MutationFunctionIntent, key)
}

func (r *Reader) ReadFunctionIntent(ctx context.Context, tenantID, functionID string) (LogEntry, error) {
	key, err := functionIntentKey(tenantID, functionID)
	if err != nil {
		return LogEntry{}, err
	}
	return r.ReadHostMutation(ctx, MutationFunctionIntent, key)
}

func (r *Runtime) CommitFunctionGrant(ctx context.Context, epoch uint64, operationID string,
	expectedSequence uint64, proof release.VerifiedFunction, binding FunctionBinding,
) (uint64, error) {
	if err := binding.Validate(); err != nil {
		return 0, err
	}
	if !proof.Valid() {
		return 0, trust.ErrExpired
	}
	claim := proof.Claim()
	if catalog.OCIRegion(claim.Cell) != binding.Region {
		return 0, release.ErrExpectationMismatch
	}
	grant := FunctionGrant{TenantID: claim.TenantID, FunctionID: claim.FunctionID,
		Sequence: claim.Sequence, EnvelopeSHA256: proof.EnvelopeSHA256(), Binding: binding}
	payload, err := json.Marshal(grant)
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationFunctionGrant, binding.TaskID, operationID,
		expectedSequence, payload, func(ctx context.Context) error {
			if err := r.VerifyFunctionIntent(ctx, proof); err != nil {
				return err
			}
			prior, err := r.ReadFunctionGrant(ctx, binding.TaskID)
			if errors.Is(err, ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			if !bytes.Equal(prior.Payload, payload) {
				return ErrConflict
			}
			return nil
		})
}

func (r *Runtime) ReadFunctionGrant(ctx context.Context, taskID string) (LogEntry, error) {
	if !functionSwarmID.MatchString(taskID) {
		return LogEntry{}, errors.New("function grant task ID is invalid")
	}
	return r.ReadHostMutation(ctx, MutationFunctionGrant, taskID)
}

func (r *Reader) ReadFunctionGrant(ctx context.Context, taskID string) (LogEntry, error) {
	if !functionSwarmID.MatchString(taskID) {
		return LogEntry{}, errors.New("function grant task ID is invalid")
	}
	return r.ReadHostMutation(ctx, MutationFunctionGrant, taskID)
}

func DecodeFunctionGrant(entry LogEntry) (FunctionGrant, error) {
	var grant FunctionGrant
	if err := json.Unmarshal(entry.Payload, &grant, json.RejectUnknownMembers(true)); err != nil {
		return grant, err
	}
	if _, err := functionIntentKey(grant.TenantID, grant.FunctionID); err != nil {
		return FunctionGrant{}, err
	}
	if entry.Kind != MutationFunctionGrant || entry.Sequence == 0 || entry.SubjectKey != grant.Binding.TaskID ||
		grant.Sequence == 0 || !validTerminalDigest(grant.EnvelopeSHA256) {
		return FunctionGrant{}, errors.New("function grant control-log identity is invalid")
	}
	return grant, grant.Binding.Validate()
}

func (r *Runtime) commitMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if r == nil {
		return 0, ErrNotLeader
	}
	if r.checkClock() != nil {
		return 0, ErrClockUnhealthy
	}
	if err := validateMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		return 0, ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		return 0, ErrFenced
	}

	subject := mutationSubject(r.config.Scope, kind, subjectKey)
	for range 8 {
		info, err := r.stream.Info(ctx)
		if err != nil {
			return 0, fmt.Errorf("read control log sequence: %w", err)
		}
		if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
			return 0, fmt.Errorf("validate control log consistency: %w", err)
		}
		leaseEntry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-unreadable"})
			return 0, err
		}
		if leaseEntry.Sequence > info.State.LastSeq {
			continue
		}
		lease, err := decodeLease(leaseEntry.Data)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-corrupt"})
			return 0, ErrLeaseCorrupt
		}
		if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released ||
			!time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, Epoch: lease.Epoch, Revision: leaseEntry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
			return 0, ErrFenced
		}

		existing, err := r.stream.GetLastMsgForSubject(ctx, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			existing = nil
		} else if err != nil {
			return 0, fmt.Errorf("read prior host mutation: %w", err)
		}
		if existing != nil && existing.Sequence > info.State.LastSeq {
			continue
		}
		if existing != nil {
			prior, decodeErr := decodeControlRecord(existing.Data)
			if decodeErr != nil {
				return 0, fmt.Errorf("decode prior host mutation: %w", decodeErr)
			}
			if prior.OperationID == operationID {
				if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
					return existing.Sequence, nil
				}
				return 0, ErrOperationConflict
			}
			if existing.Sequence != expectedSubjectSequence {
				return 0, ErrConflict
			}
		} else if expectedSubjectSequence != 0 {
			return 0, ErrConflict
		}
		if verify != nil {
			if err := r.verify(ctx, expectedEpoch, leaseEntry.Sequence, info.State.LastSeq,
				subject, operationID, leaseEntry.Time.Add(time.Duration(lease.LeaseDuration)), verify); err != nil {
				return 0, err
			}
			if !time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
				return 0, ErrFenced
			}
		}

		record := controlRecord{
			Version: 1, Kind: kind, Scope: r.config.Scope, SubjectKey: subjectKey,
			OperationID: operationID, Epoch: expectedEpoch, Payload: bytes.Clone(payload),
		}
		data, err := json.Marshal(record)
		if err != nil {
			return 0, err
		}
		msg := controlMessage(subject, string(kind), operationID, data)
		ack, err := r.js.PublishMsg(ctx, msg,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSubjectSequence, subject),
		)
		if err == nil {
			return ack.Sequence, nil
		}
		if isSequenceConflict(err) {
			latest, readErr := r.stream.GetLastMsgForSubject(ctx, subject)
			if readErr == nil {
				prior, decodeErr := decodeControlRecord(latest.Data)
				if decodeErr == nil && prior.OperationID == operationID {
					if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
						return latest.Sequence, nil
					}
					return 0, ErrOperationConflict
				}
				if latest.Sequence != expectedSubjectSequence {
					return 0, ErrConflict
				}
			}
			continue
		}
		return r.resolveUnknownMutation(ctx, subject, kind, subjectKey, operationID, expectedEpoch, payload, err)
	}
	return 0, ErrConflict
}

// ReadHostMutation reads the current committed host record.
func (r *Runtime) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil

func OpenStore(ctx context.Context, js jetstream.JetStream, cell string, fencer authority.Fencer) (*Store, error) {
	if js == nil || !brokerToken.MatchString(cell) {
		return nil, errors.New("broker claim store requires a regional JetStream cell")
	}
	stream, err := js.Stream(ctx, authority.ControlStreamName)
	if err != nil {
		return nil, fmt.Errorf("open broker claim control log: %w", err)
	}
	info, err := stream.Info(ctx)
	if err != nil {
		return nil, fmt.Errorf("inspect broker claim control log: %w", err)
	}
	if info.Config.Name != authority.ControlStreamName || info.Config.AllowDirect ||
		!info.Config.DenyDelete || !info.Config.DenyPurge ||
		info.Config.Retention != jetstream.LimitsPolicy || info.Config.Storage != jetstream.FileStorage ||
		info.Config.MaxMsgs != -1 || info.Config.MaxBytes != -1 || info.Config.MaxMsgsPerSubject != -1 ||
		info.Config.MaxAge != 0 || info.Config.Discard != jetstream.DiscardOld ||
		info.Config.DiscardNewPerSubject || info.Config.AllowRollup ||
		info.Config.Metadata["terrascale-contract"] != "authority-log-v1" ||
		len(info.Config.Subjects) != 1 || info.Config.Subjects[0] != protocol.ControlStreamSubject() {
		return nil, errors.New("broker claim control log is not durable and leader-read")
	}
	return &Store{js: js, stream: stream, cell: cell, fencer: fencer}, nil
}

func (s *Store) Read(ctx context.Context, account string) (Claim, error) {
	if s == nil || s.stream == nil || !nkeys.IsValidPublicAccountKey(account) {
		return Claim{}, ErrNoClaim
	}
	entry, err := s.stream.GetLastMsgForSubject(ctx, claimSubject(s.cell, account))
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return Claim{}, ErrNoClaim
	}
	if err != nil {
		return Claim{}, fmt.Errorf("read current broker claim: %w", err)
	}
	var record claimRecord
	if len(entry.Data) == 0 || len(entry.Data) > maxAccountJWTBytes+4096 ||
		json.Unmarshal(entry.Data, &record, json.RejectUnknownMembers(true)) != nil ||
		record.Version != 1 || record.Cell != s.cell || record.Account != account || record.Epoch == 0 {
		return Claim{}, errors.New("durable broker claim record is invalid")
	}
	decoded, err := DecodeAccountJWT(record.JWT, account)
	if err != nil || decoded.IssuedAt != record.IssuedAt {
		return Claim{}, errors.New("durable broker claim JWT is invalid")
	}
	digest := sha256.Sum256([]byte(record.JWT))
	return Claim{Cell: s.cell, Account: account, JWT: record.JWT,
		Hash: hex.EncodeToString(digest[:]), Sequence: entry.Sequence, Epoch: record.Epoch,
		IssuedAt: record.IssuedAt, Committed: entry.Time}, nil
}

// Commit appends one higher-iAT account claim under the current authority
// lease. A global sequence CAS prevents an old epoch from writing past a new
// lease barrier. Repeating the exact prior JWT is idempotent.
func (s *Store) Commit(ctx context.Context, epoch uint64, account, raw string, expectedSequence uint64) (Claim, error) {
	if s == nil || s.fencer == nil || epoch == 0 {
		return Claim{}, authority.ErrNotLeader
	}
	decoded, err := DecodeAccountJWT(raw, account)
	if err != nil {
		return Claim{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for range 8 {
		if err := s.fencer.Guard(ctx, epoch); err != nil {
			return Claim{}, err
		}
		snapshot := s.fencer.Current()
		if !snapshot.CanMutate() || snapshot.Scope != s.cell || snapshot.Epoch != epoch {
			return Claim{}, authority.ErrFenced
		}
		prior, err := s.Read(ctx, account)
		if err != nil && !errors.Is(err, ErrNoClaim) {
			return Claim{}, err
		}
		if prior.Sequence != 0 {
			if prior.JWT == raw {
				return prior, nil
			}
		}
		if prior.Sequence != expectedSequence {
			return Claim{}, authority.ErrConflict
		}
		if prior.Sequence != 0 {
			if decoded.IssuedAt <= prior.IssuedAt {
				return Claim{}, errors.New("replacement account JWT issued-at must strictly increase")
			}
		}
		info, err := s.stream.Info(ctx)
		if err != nil {
			return Claim{}, err
		}
		observed, err := authority.Observe(ctx, s.js, s.cell)
		if err != nil || !observed.Ready || observed.DeploymentID != snapshot.DeploymentID || observed.Epoch != epoch ||
			observed.CandidateID != snapshot.CandidateID || observed.OwnerID != snapshot.OwnerID ||
			observed.Revision > info.State.LastSeq {
			return Claim{}, authority.ErrFenced
		}
		record := claimRecord{Version: 1, Cell: s.cell, Account: account, JWT: raw,
			Epoch: epoch, IssuedAt: decoded.IssuedAt}
		data, err := json.Marshal(record)
		if err != nil {
			return Claim{}, err
		}
		message := &nats.Msg{Subject: claimSubject(s.cell, account), Data: data}
		ack, err := s.js.PublishMsg(ctx, message,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSequence, message.Subject))
		if err != nil {
			if ctx.Err() != nil {
				return Claim{}, ctx.Err()
			}
			// A competing lease or claim append requires a fresh Guard. No
			// uncertain publish is reported successful without read-back.
			current, readErr := s.Read(ctx, account)
			if readErr == nil && current.Sequence > expectedSequence {
				if bytes.Equal([]byte(current.JWT), []byte(raw)) && current.Epoch == epoch {
					return current, nil
				}
				return Claim{}, authority.ErrConflict
			}
			continue
		}
		current, err := s.Read(ctx, account)
		if err != nil || current.Sequence != ack.Sequence || current.JWT != raw || current.Epoch != epoch {
			return Claim{}, authority.ErrOutcomeUnknown
		}
		return current, nil
	}
	return Claim{}, authority.ErrConflict
}

func ProvisionQueue(ctx context.Context, nc *nats.Conn, admitted release.VerifiedFunction) error {
	if !admitted.Valid() {
		return ErrScope
	}
	claim := admitted.Claim()
	manifest := Manifest{ABI: claim.ABI, TenantID: claim.TenantID, FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, Capabilities: claim.Capabilities}
	ctx, cancel := context.WithDeadline(ctx, admitted.ExpiresAt())
	defer cancel()
	return provisionQueue(ctx, nc, manifest)
}

func provisionQueue(ctx context.Context, nc *nats.Conn, manifest Manifest) error {
	if nc == nil {
		return fmt.Errorf("%w: broker required", ErrInvalid)
	}
	scope, err := QueueIdentity(manifest)
	if err != nil {
		return err
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return err
	}
	_, err = js.CreateOrUpdateStream(ctx, jetstream.StreamConfig{Name: scope.Stream, Subjects: []string{scope.Subject},
		Storage: jetstream.FileStorage, Retention: jetstream.WorkQueuePolicy, Discard: jetstream.DiscardNew,
		MaxAge: time.Hour, MaxMsgs: 10000, MaxBytes: 64 << 20, MaxMsgSize: MaxPayloadBytes + 8192, Duplicates: 2 * time.Minute})
	if err != nil {
		return fmt.Errorf("function queue: %w", err)
	}
	_, err = js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: scope.ReceiptBucket, Storage: jetstream.FileStorage, History: 1, TTL: 24 * time.Hour, MaxBytes: 64 << 20, MaxValueSize: 512})
	if err != nil {
		return fmt.Errorf("function receipts: %w", err)
	}
	_, err = js.CreateOrUpdateConsumer(ctx, scope.Stream, jetstream.ConsumerConfig{Durable: "worker", FilterSubject: scope.Subject, AckPolicy: jetstream.AckExplicitPolicy, AckWait: 30 * time.Second, MaxDeliver: -1, MaxAckPending: 1, MaxWaiting: 32, MaxRequestBatch: 1, MaxRequestExpires: time.Second})
	if err != nil {
		return fmt.Errorf("function consumer: %w", err)
	}
	return nil
}

